-- ============================================
-- KPI Query System - Complete Setup
-- ============================================

-- Step 1: Clean up
DROP TABLE IF EXISTS kpi_data CASCADE;
DROP TABLE IF EXISTS profiles CASCADE;
DROP FUNCTION IF EXISTS public.check_employee(TEXT, TEXT);
DROP FUNCTION IF EXISTS public.handle_new_user();

-- Step 2: Create kpi_data table
CREATE TABLE kpi_data (
  id BIGSERIAL PRIMARY KEY,
  "工号" TEXT,
  "姓名" TEXT,
  "星级" TEXT,
  "区县" TEXT,
  "归属分局" TEXT,
  "净增积分_得分" NUMERIC,
  "融合宽带+两线_得分" NUMERIC,
  "FTTR-B_得分" NUMERIC,
  "视联网云存_得分" NUMERIC,
  "酒美_得分" NUMERIC,
  "基础执行(客户拜访)_得分" NUMERIC,
  "存量维系(欠停复机率)_得分" NUMERIC,
  "标准ICT高阶版_得分" NUMERIC,
  "云电脑_得分" NUMERIC,
  "小微ICT_得分" NUMERIC,
  "阶段重点工作_得分" NUMERIC,
  "协议续签_得分" NUMERIC,
  "翼锐智投_得分" NUMERIC,
  "量子_得分" NUMERIC,
  "安全_得分" NUMERIC,
  "服务投诉_得分" NUMERIC,
  "分局长打分_得分" NUMERIC,
  "积分_得分" NUMERIC,
  "重点业务_得分" NUMERIC,
  "规定动作_得分" NUMERIC,
  "加扣分项_得分" NUMERIC,
  "KPI总得分" NUMERIC,
  "总分排名" NUMERIC,
  "积分_团队均值" NUMERIC,
  "重点业务_团队均值" NUMERIC,
  "规定动作_团队均值" NUMERIC,
  "加扣分项_团队均值" NUMERIC,
  "分局长打分_团队均值" NUMERIC,
  "KPI团队均值" NUMERIC,
  "KPI团队标准差" NUMERIC,
  "KPI团队最高分" NUMERIC,
  "优势项" TEXT,
  "短板项" TEXT
, created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Step 3: Create profiles table
CREATE TABLE profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  emp_id TEXT UNIQUE NOT NULL,
  emp_name TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Step 4: Enable RLS
ALTER TABLE kpi_data ENABLE ROW LEVEL SECURITY;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

-- Step 5: RLS Policies
CREATE POLICY "Users can view own kpi data"
ON kpi_data FOR SELECT
USING (
  "工号" IN (SELECT p.emp_id FROM profiles p WHERE p.id = auth.uid())
);

CREATE POLICY "Users can view own profile"
ON profiles FOR SELECT
USING (id = auth.uid());

-- Step 6: Trigger for auto profile creation
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, emp_id, emp_name)
  VALUES (NEW.id, NEW.raw_user_meta_data->>'emp_id', NEW.raw_user_meta_data->>'emp_name');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- Step 7: Employee verification function
CREATE OR REPLACE FUNCTION public.check_employee(eid TEXT, ename TEXT)
RETURNS BOOLEAN AS $$
DECLARE found BOOLEAN;
BEGIN
  SELECT EXISTS (SELECT 1 FROM kpi_data WHERE "工号" = eid AND "姓名" = ename) INTO found;
  RETURN found;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.check_employee(TEXT, TEXT) TO anon, authenticated;

